<template><div class="app-layout"><aside class="sidebar"><div class="brand">产品管理系统</div><el-menu :default-active="$route.path" router background-color="#111827" text-color="#d1d5db" active-text-color="#fff"><el-menu-item index="/products">产品列表</el-menu-item><el-menu-item v-if="auth.isAdmin" index="/categories">分类管理</el-menu-item><el-menu-item v-if="auth.isAdmin" index="/users">员工账号</el-menu-item></el-menu></aside><section class="main"><header class="topbar"><div><b>{{ pageTitle }}</b></div><div><span style="margin-right:12px">{{auth.user?.displayName}}</span><el-tag size="small">{{auth.isAdmin?'管理员':'员工'}}</el-tag><el-button link @click="logout">退出</el-button></div></header><main class="content"><router-view/></main></section></div></template>
<script setup>import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';const auth=useAuthStore(),r=useRouter(),route=useRoute();const pageTitle=computed(()=>route.path.includes('users')?'员工账号':route.path.includes('categories')?'分类管理':'产品列表');function logout(){auth.logout();r.push('/login')}</script>
